#include <iostream>

#include <queue>

#include <vector>

#include <functional>

using namespace std;

int main() {

    // 최소 힙

    priority_queue<int, vector<int>, greater<int>> minHeap;

    minHeap.push(5);

    minHeap.push(1);

    minHeap.push(3);

    cout << minHeap.top(); minHeap.pop(); cout << "\n"; // 1

    cout << minHeap.top(); minHeap.pop(); cout << "\n"; // 3

    cout << minHeap.top(); minHeap.pop(); cout << "\n"; // 5

    // 최대 힙

    priority_queue<int> maxHeap;

    maxHeap.push(5);

    maxHeap.push(1);

    maxHeap.push(3);

    cout << maxHeap.top(); maxHeap.pop(); cout << "\n"; // 5

    cout << maxHeap.top(); maxHeap.pop(); cout << "\n"; // 3

    cout << maxHeap.top(); maxHeap.pop(); cout << "\n"; // 1

    return 0;

}

